-- create-table /RT/LANGUAGES
CREATE TABLE "/RT/LANGUAGES" (
  "LANGUAGE" VARCHAR(2) COLLATE "C" NOT NULL,
  "NAME" VARCHAR(60) COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/LANGUAGES#PK" PRIMARY KEY ("LANGUAGE")
);

-- create-table /RT/TENANTS
CREATE TABLE "/RT/TENANTS" (
  "TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "DESCRIPTION" TEXT COLLATE "C",
  "CREATED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/TENANTS#PK" PRIMARY KEY ("TENANT")
);

-- create-table /RT/USERS
CREATE TABLE "/RT/USERS" (
  "USER_NAME" VARCHAR(64) COLLATE "C" NOT NULL,
  "STATUS" VARCHAR(6) COLLATE "C" NOT NULL,
  "LANGUAGE" VARCHAR(2) COLLATE "C",
  "DEFAULT_TENANT" VARCHAR(16) COLLATE "C",
  "PASSWORD_HASH" TEXT COLLATE "C",
  "FAILED_LOGINS" INTEGER NOT NULL,
  "LOCKED_AT" TIMESTAMPTZ,
  "CREATED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/USERS#PK" PRIMARY KEY ("USER_NAME"),
  CONSTRAINT "/RT/USERS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/USERS#FK#DEFAULT_TENANT" FOREIGN KEY ("DEFAULT_TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/USERS#CK#STATUS" CHECK ("STATUS" IN ('active', 'locked'))
);

-- create-table /RT/API_TOKENS
CREATE TABLE "/RT/API_TOKENS" (
  "TOKEN_ID" UUID NOT NULL,
  "USER_NAME" VARCHAR(64) COLLATE "C" NOT NULL,
  "LABEL" VARCHAR(80) COLLATE "C" NOT NULL,
  "EXPIRES_AT" TIMESTAMPTZ,
  "TOKEN_HASH" VARCHAR(64) COLLATE "C" NOT NULL,
  "CREATED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/API_TOKENS#PK" PRIMARY KEY ("TOKEN_ID"),
  CONSTRAINT "/RT/API_TOKENS#FK#USER" FOREIGN KEY ("USER_NAME") REFERENCES "/RT/USERS" ("USER_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/PACKAGES
CREATE TABLE "/RT/PACKAGES" (
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "VERSION" VARCHAR(64) COLLATE "C" NOT NULL,
  "DESCRIPTION" TEXT COLLATE "C",
  "INSTALLED_AT" TIMESTAMPTZ NOT NULL,
  "UPDATED_AT" TIMESTAMPTZ NOT NULL,
  "LANGUAGE_VERSION" INTEGER,
  "KERNEL_PACKAGE" BOOLEAN NOT NULL DEFAULT FALSE,
  CONSTRAINT "/RT/PACKAGES#PK" PRIMARY KEY ("PACKAGE_ID")
);

-- create-table /RT/ARRAY_TYPES
CREATE TABLE "/RT/ARRAY_TYPES" (
  "ARRAY_TYPE" VARCHAR(63) COLLATE "C" NOT NULL,
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "ROW_KIND" VARCHAR(12) COLLATE "C" NOT NULL,
  "ROW_TYPE" VARCHAR(63) COLLATE "C" NOT NULL,
  "KEY_UNIQUE" BOOLEAN,
  CONSTRAINT "/RT/ARRAY_TYPES#PK" PRIMARY KEY ("ARRAY_TYPE"),
  CONSTRAINT "/RT/ARRAY_TYPES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ARRAY_TYPES#CK#ROW_KIND" CHECK ("ROW_KIND" IN ('DATA_ELEMENT', 'DOMAIN', 'STRUCTURE', 'ARRAY_TYPE'))
);

-- create-table /RT/ARRAY_TYPE_KEYS
CREATE TABLE "/RT/ARRAY_TYPE_KEYS" (
  "ARRAY_TYPE" VARCHAR(63) COLLATE "C" NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "FIELD_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/ARRAY_TYPE_KEYS#PK" PRIMARY KEY ("ARRAY_TYPE", "POSITION"),
  CONSTRAINT "/RT/ARRAY_TYPE_KEYS#FK#ARRAY_TYPE" FOREIGN KEY ("ARRAY_TYPE") REFERENCES "/RT/ARRAY_TYPES" ("ARRAY_TYPE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ARRAY_TYPE_TEXTS
CREATE TABLE "/RT/ARRAY_TYPE_TEXTS" (
  "ARRAY_TYPE" VARCHAR(63) COLLATE "C" NOT NULL,
  "LANGUAGE" VARCHAR(2) COLLATE "C" NOT NULL,
  "LABEL" VARCHAR(60) COLLATE "C" NOT NULL,
  "DESCRIPTION" TEXT COLLATE "C",
  CONSTRAINT "/RT/ARRAY_TYPE_TEXTS#PK" PRIMARY KEY ("ARRAY_TYPE", "LANGUAGE"),
  CONSTRAINT "/RT/ARRAY_TYPE_TEXTS#FK#ARRAY_TYPE" FOREIGN KEY ("ARRAY_TYPE") REFERENCES "/RT/ARRAY_TYPES" ("ARRAY_TYPE") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ARRAY_TYPE_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_BLOBS
CREATE TABLE "/RT/ASSET_BLOBS" (
  "SHA256" VARCHAR(64) COLLATE "C" NOT NULL,
  "SIZE" BIGINT NOT NULL,
  "CHUNKS" INTEGER NOT NULL,
  CONSTRAINT "/RT/ASSET_BLOBS#PK" PRIMARY KEY ("SHA256")
);

-- create-table /RT/ASSET_CHUNKS
CREATE TABLE "/RT/ASSET_CHUNKS" (
  "SHA256" VARCHAR(64) COLLATE "C" NOT NULL,
  "SEQ" INTEGER NOT NULL,
  "DATA" BYTEA NOT NULL,
  CONSTRAINT "/RT/ASSET_CHUNKS#PK" PRIMARY KEY ("SHA256", "SEQ"),
  CONSTRAINT "/RT/ASSET_CHUNKS#FK#BLOB" FOREIGN KEY ("SHA256") REFERENCES "/RT/ASSET_BLOBS" ("SHA256") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_REPOSITORIES
CREATE TABLE "/RT/ASSET_REPOSITORIES" (
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/ASSET_REPOSITORIES#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID"),
  CONSTRAINT "/RT/ASSET_REPOSITORIES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_ENTRIES
CREATE TABLE "/RT/ASSET_ENTRIES" (
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) COLLATE "C" NOT NULL,
  "PATH" VARCHAR(255) COLLATE "C" NOT NULL,
  "KIND" VARCHAR(6) COLLATE "C" NOT NULL,
  "PARENT_PATH" VARCHAR(255) COLLATE "C",
  "MIME_TYPE" VARCHAR(127) COLLATE "C",
  "SHA256" VARCHAR(64) COLLATE "C",
  "SIZE" BIGINT,
  "SOURCE_PATH" VARCHAR(255) COLLATE "C",
  "MODIFIED_AT" TIMESTAMPTZ,
  CONSTRAINT "/RT/ASSET_ENTRIES#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH"),
  CONSTRAINT "/RT/ASSET_ENTRIES#FK#REPOSITORY" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID") REFERENCES "/RT/ASSET_REPOSITORIES" ("PACKAGE_ID", "REPOSITORY_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_ENTRIES#FK#PARENT" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID", "PARENT_PATH") REFERENCES "/RT/ASSET_ENTRIES" ("PACKAGE_ID", "REPOSITORY_ID", "PATH") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_ENTRIES#FK#BLOB" FOREIGN KEY ("SHA256") REFERENCES "/RT/ASSET_BLOBS" ("SHA256") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_ENTRIES#CK#KIND" CHECK ("KIND" IN ('FOLDER', 'FILE'))
);

-- create-table /RT/ASSET_ENTRY_TEXTS
CREATE TABLE "/RT/ASSET_ENTRY_TEXTS" (
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) COLLATE "C" NOT NULL,
  "PATH" VARCHAR(255) COLLATE "C" NOT NULL,
  "LANGUAGE" VARCHAR(2) COLLATE "C" NOT NULL,
  "DESCRIPTION" TEXT COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/ASSET_ENTRY_TEXTS#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH", "LANGUAGE"),
  CONSTRAINT "/RT/ASSET_ENTRY_TEXTS#FK#ENTRY" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH") REFERENCES "/RT/ASSET_ENTRIES" ("PACKAGE_ID", "REPOSITORY_ID", "PATH") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_ENTRY_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_REPOSITORY_TEXTS
CREATE TABLE "/RT/ASSET_REPOSITORY_TEXTS" (
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) COLLATE "C" NOT NULL,
  "LANGUAGE" VARCHAR(2) COLLATE "C" NOT NULL,
  "DESCRIPTION" TEXT COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/ASSET_REPOSITORY_TEXTS#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID", "LANGUAGE"),
  CONSTRAINT "/RT/ASSET_REPOSITORY_TEXTS#FK#REPOSITORY" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID") REFERENCES "/RT/ASSET_REPOSITORIES" ("PACKAGE_ID", "REPOSITORY_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_REPOSITORY_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_VARIANTS
CREATE TABLE "/RT/ASSET_VARIANTS" (
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) COLLATE "C" NOT NULL,
  "PATH" VARCHAR(255) COLLATE "C" NOT NULL,
  "LANGUAGE" VARCHAR(2) COLLATE "C" NOT NULL,
  "SOURCE_PATH" VARCHAR(255) COLLATE "C" NOT NULL,
  "SHA256" VARCHAR(64) COLLATE "C" NOT NULL,
  "SIZE" BIGINT NOT NULL,
  "MODIFIED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/ASSET_VARIANTS#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH", "LANGUAGE"),
  CONSTRAINT "/RT/ASSET_VARIANTS#FK#ENTRY" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH") REFERENCES "/RT/ASSET_ENTRIES" ("PACKAGE_ID", "REPOSITORY_ID", "PATH") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_VARIANTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_VARIANTS#FK#BLOB" FOREIGN KEY ("SHA256") REFERENCES "/RT/ASSET_BLOBS" ("SHA256") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/AUTH_GENERATION
CREATE TABLE "/RT/AUTH_GENERATION" (
  "ID" INTEGER NOT NULL,
  "GENERATION" BIGINT NOT NULL,
  "CHANGED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/AUTH_GENERATION#PK" PRIMARY KEY ("ID")
);

-- create-table /RT/AUTH_LAST_FAILED
CREATE TABLE "/RT/AUTH_LAST_FAILED" (
  "USER_NAME" VARCHAR(64) COLLATE "C" NOT NULL,
  "TENANT" VARCHAR(16) COLLATE "C" NOT NULL,
  "FAILED_AT" TIMESTAMPTZ NOT NULL,
  "OBJECT_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "CHECK_VALUES" TEXT COLLATE "C" NOT NULL,
  "PACKAGE_ID" VARCHAR(16) COLLATE "C",
  "CLASS_NAME" VARCHAR(63) COLLATE "C",
  "METHOD_NAME" VARCHAR(63) COLLATE "C",
  "LINE_NO" INTEGER,
  "KERNEL_FUNCTION" VARCHAR(120) COLLATE "C",
  "GRANTS" TEXT COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/AUTH_LAST_FAILED#PK" PRIMARY KEY ("USER_NAME", "TENANT")
);

-- create-table /RT/AUTH_OBJECTS
CREATE TABLE "/RT/AUTH_OBJECTS" (
  "OBJECT_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "FILE_PATH" VARCHAR(255) COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/AUTH_OBJECTS#PK" PRIMARY KEY ("OBJECT_NAME"),
  CONSTRAINT "/RT/AUTH_OBJECTS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/AUTH_OBJECT_ACTIVITIES
CREATE TABLE "/RT/AUTH_OBJECT_ACTIVITIES" (
  "OBJECT_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "ACTIVITY" VARCHAR(16) COLLATE "C" NOT NULL,
  "POSITION" INTEGER NOT NULL,
  CONSTRAINT "/RT/AUTH_OBJECT_ACTIVITIES#PK" PRIMARY KEY ("OBJECT_NAME", "ACTIVITY"),
  CONSTRAINT "/RT/AUTH_OBJECT_ACTIVITIES#FK#OBJECT" FOREIGN KEY ("OBJECT_NAME") REFERENCES "/RT/AUTH_OBJECTS" ("OBJECT_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/AUTH_OBJECT_ACTIVITIES#CK#ACTIVITY" CHECK ("ACTIVITY" <> '' AND "ACTIVITY" IN ('READ', 'CREATE', 'UPDATE', 'DELETE', 'EXECUTE', 'APPROVE', 'REJECT', 'CANCEL', 'IMPORT', 'EXPORT', 'PRINT', 'SEND', 'ADMINISTER'))
);

-- create-table /RT/AUTH_OBJECT_FIELDS
CREATE TABLE "/RT/AUTH_OBJECT_FIELDS" (
  "OBJECT_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "FIELD_NAME" VARCHAR(30) COLLATE "C" NOT NULL,
  "DATA_ELEMENT" VARCHAR(63) COLLATE "C",
  "DOMAIN_NAME" VARCHAR(63) COLLATE "C",
  CONSTRAINT "/RT/AUTH_OBJECT_FIELDS#PK" PRIMARY KEY ("OBJECT_NAME", "POSITION"),
  CONSTRAINT "/RT/AUTH_OBJECT_FIELDS#FK#OBJECT" FOREIGN KEY ("OBJECT_NAME") REFERENCES "/RT/AUTH_OBJECTS" ("OBJECT_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/AUTH_OBJECT_TEXTS
CREATE TABLE "/RT/AUTH_OBJECT_TEXTS" (
  "OBJECT_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "LANGUAGE" VARCHAR(2) COLLATE "C" NOT NULL,
  "LABEL" VARCHAR(60) COLLATE "C" NOT NULL,
  "DESCRIPTION" TEXT COLLATE "C",
  CONSTRAINT "/RT/AUTH_OBJECT_TEXTS#PK" PRIMARY KEY ("OBJECT_NAME", "LANGUAGE"),
  CONSTRAINT "/RT/AUTH_OBJECT_TEXTS#FK#OBJECT" FOREIGN KEY ("OBJECT_NAME") REFERENCES "/RT/AUTH_OBJECTS" ("OBJECT_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/AUTH_OBJECT_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/AUTH_TRACES
CREATE TABLE "/RT/AUTH_TRACES" (
  "USER_NAME" VARCHAR(64) COLLATE "C" NOT NULL,
  "TENANT" VARCHAR(16) COLLATE "C",
  "STARTED_AT" TIMESTAMPTZ NOT NULL,
  "UNTIL" TIMESTAMPTZ NOT NULL,
  "MAX_ENTRIES" INTEGER NOT NULL,
  "STARTED_BY" VARCHAR(64) COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/AUTH_TRACES#PK" PRIMARY KEY ("USER_NAME")
);

-- create-table /RT/AUTH_TRACE_ENTRIES
CREATE TABLE "/RT/AUTH_TRACE_ENTRIES" (
  "ENTRY_ID" UUID NOT NULL,
  "CHECKED_AT" TIMESTAMPTZ NOT NULL,
  "USER_NAME" VARCHAR(64) COLLATE "C" NOT NULL,
  "TENANT" VARCHAR(16) COLLATE "C",
  "CHECK_MODE" VARCHAR(10) COLLATE "C" NOT NULL,
  "OBJECT_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "ALLOWED" BOOLEAN,
  "CHECK_VALUES" TEXT COLLATE "C" NOT NULL,
  "PACKAGE_ID" VARCHAR(16) COLLATE "C",
  "CLASS_NAME" VARCHAR(63) COLLATE "C",
  "METHOD_NAME" VARCHAR(63) COLLATE "C",
  "LINE_NO" INTEGER,
  "KERNEL_FUNCTION" VARCHAR(120) COLLATE "C",
  "CONDITION_SQL" TEXT COLLATE "C",
  "ROW_COUNT" BIGINT,
  CONSTRAINT "/RT/AUTH_TRACE_ENTRIES#PK" PRIMARY KEY ("ENTRY_ID"),
  CONSTRAINT "/RT/AUTH_TRACE_ENTRIES#CK#CHECK_MODE" CHECK ("CHECK_MODE" IN ('check', 'expression', 'filter', 'entity'))
);

-- create-table /RT/BUSINESS_OBJECTS
CREATE TABLE "/RT/BUSINESS_OBJECTS" (
  "BO_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "FILE_PATH" VARCHAR(255) COLLATE "C" NOT NULL,
  "ROOT_TABLE" VARCHAR(63) COLLATE "C" NOT NULL,
  "BEHAVIOR_CLASS" VARCHAR(63) COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/BUSINESS_OBJECTS#PK" PRIMARY KEY ("BO_NAME"),
  CONSTRAINT "/RT/BUSINESS_OBJECTS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/BUSINESS_OBJECT_ENTITIES
CREATE TABLE "/RT/BUSINESS_OBJECT_ENTITIES" (
  "BO_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "TABLE_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "PARENT_TABLE" VARCHAR(63) COLLATE "C",
  "FK_NAME" VARCHAR(63) COLLATE "C",
  "NUMBERING" VARCHAR(8) COLLATE "C" NOT NULL,
  "CAN_CREATE" BOOLEAN NOT NULL,
  "CAN_UPDATE" BOOLEAN NOT NULL,
  "CAN_DELETE" BOOLEAN NOT NULL,
  "CREATED_BY" VARCHAR(63) COLLATE "C",
  "CREATED_AT" VARCHAR(63) COLLATE "C",
  "CHANGED_BY" VARCHAR(63) COLLATE "C",
  "CHANGED_AT" VARCHAR(63) COLLATE "C",
  "ETAG_FIELD" VARCHAR(63) COLLATE "C",
  "AUTH_OBJECT" VARCHAR(63) COLLATE "C",
  CONSTRAINT "/RT/BUSINESS_OBJECT_ENTITIES#PK" PRIMARY KEY ("BO_NAME", "TABLE_NAME"),
  CONSTRAINT "/RT/BUSINESS_OBJECT_ENTITIES#FK#BUSINESS_OBJECT" FOREIGN KEY ("BO_NAME") REFERENCES "/RT/BUSINESS_OBJECTS" ("BO_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/BUSINESS_OBJECT_ENTITIES#CK#NUMBERING" CHECK ("NUMBERING" IN ('external', 'uuid'))
);

-- create-table /RT/BUSINESS_OBJECT_AUTH
CREATE TABLE "/RT/BUSINESS_OBJECT_AUTH" (
  "BO_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "TABLE_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "MAPPING_KIND" VARCHAR(8) COLLATE "C" NOT NULL,
  "MAPPING_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "MAPPING_VALUE" VARCHAR(63) COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/BUSINESS_OBJECT_AUTH#PK" PRIMARY KEY ("BO_NAME", "TABLE_NAME", "MAPPING_KIND", "MAPPING_NAME"),
  CONSTRAINT "/RT/BUSINESS_OBJECT_AUTH#FK#ENTITY" FOREIGN KEY ("BO_NAME", "TABLE_NAME") REFERENCES "/RT/BUSINESS_OBJECT_ENTITIES" ("BO_NAME", "TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/BUSINESS_OBJECT_AUTH#CK#MAPPING_KIND" CHECK ("MAPPING_KIND" IN ('field', 'activity'))
);

-- create-table /RT/BUSINESS_OBJECT_FIELDS
CREATE TABLE "/RT/BUSINESS_OBJECT_FIELDS" (
  "BO_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "TABLE_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "FIELD_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "READ_ONLY" BOOLEAN NOT NULL,
  "READ_ONLY_ON_UPDATE" BOOLEAN NOT NULL,
  "MANDATORY" BOOLEAN NOT NULL,
  CONSTRAINT "/RT/BUSINESS_OBJECT_FIELDS#PK" PRIMARY KEY ("BO_NAME", "TABLE_NAME", "FIELD_NAME"),
  CONSTRAINT "/RT/BUSINESS_OBJECT_FIELDS#FK#ENTITY" FOREIGN KEY ("BO_NAME", "TABLE_NAME") REFERENCES "/RT/BUSINESS_OBJECT_ENTITIES" ("BO_NAME", "TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/BUSINESS_OBJECT_METHODS
CREATE TABLE "/RT/BUSINESS_OBJECT_METHODS" (
  "BO_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "METHOD_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "TABLE_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "METHOD_KIND" VARCHAR(16) COLLATE "C" NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "RUNS_WHEN" VARCHAR(8) COLLATE "C",
  "ON_CREATE" BOOLEAN NOT NULL,
  "ON_UPDATE" BOOLEAN NOT NULL,
  "ON_DELETE" BOOLEAN NOT NULL,
  "IS_INSTANCE" BOOLEAN NOT NULL,
  "PARAMETER_TYPE" VARCHAR(63) COLLATE "C",
  "RESULT_TYPE" VARCHAR(63) COLLATE "C",
  "MODIFIES" BOOLEAN NOT NULL,
  CONSTRAINT "/RT/BUSINESS_OBJECT_METHODS#PK" PRIMARY KEY ("BO_NAME", "METHOD_NAME"),
  CONSTRAINT "/RT/BUSINESS_OBJECT_METHODS#FK#ENTITY" FOREIGN KEY ("BO_NAME", "TABLE_NAME") REFERENCES "/RT/BUSINESS_OBJECT_ENTITIES" ("BO_NAME", "TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/BUSINESS_OBJECT_METHODS#CK#METHOD_KIND" CHECK ("METHOD_KIND" IN ('determination', 'validation', 'action')),
  CONSTRAINT "/RT/BUSINESS_OBJECT_METHODS#CK#RUNS_WHEN" CHECK ("RUNS_WHEN" IN ('modify', 'save'))
);

-- create-table /RT/BUSINESS_OBJECT_TEXTS
CREATE TABLE "/RT/BUSINESS_OBJECT_TEXTS" (
  "BO_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "LANGUAGE" VARCHAR(2) COLLATE "C" NOT NULL,
  "DESCRIPTION" VARCHAR(60) COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/BUSINESS_OBJECT_TEXTS#PK" PRIMARY KEY ("BO_NAME", "LANGUAGE"),
  CONSTRAINT "/RT/BUSINESS_OBJECT_TEXTS#FK#BUSINESS_OBJECT" FOREIGN KEY ("BO_NAME") REFERENCES "/RT/BUSINESS_OBJECTS" ("BO_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/BUSINESS_OBJECT_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/BUSINESS_OBJECT_TRIGGER_FIELDS
CREATE TABLE "/RT/BUSINESS_OBJECT_TRIGGER_FIELDS" (
  "BO_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "METHOD_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "FIELD_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  CONSTRAINT "/RT/BUSINESS_OBJECT_TRIGGER_FIELDS#PK" PRIMARY KEY ("BO_NAME", "METHOD_NAME", "POSITION"),
  CONSTRAINT "/RT/BUSINESS_OBJECT_TRIGGER_FIELDS#FK#METHOD" FOREIGN KEY ("BO_NAME", "METHOD_NAME") REFERENCES "/RT/BUSINESS_OBJECT_METHODS" ("BO_NAME", "METHOD_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

