CREATE TABLE "/RT/CODE_GENERATION" (
  "ID" INTEGER NOT NULL,
  "GENERATION" BIGINT NOT NULL,
  "CHANGED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/CODE_GENERATION#PK" PRIMARY KEY ("ID")
);

-- create-table /RT/CODE_INCLUDES
CREATE TABLE "/RT/CODE_INCLUDES" (
  "PACKAGE_ID" VARCHAR(16) COLLATE "C" NOT NULL,
  "INCLUDE_NAME" VARCHAR(63) COLLATE "C" NOT NULL,
  "INCLUDE_PACKAGE" VARCHAR(16) COLLATE "C" NOT NULL,
  "IF_FOUND" BOOLEAN NOT NULL,
